Literal.Value:
'{
  "data": {
    "name": "dataset"
  },
  "width": "container",
  "height": "container",
  "transform": [
    {
      "filter": "isValid(datum[''Não realizada (GWh)'']) || isValid(datum[''Geração (GWh)''])"
    },
    {
      "calculate": "(datum[''Não realizada (GWh)''] || 0) / ((datum[''Geração (GWh)''] || 0) + (datum[''Não realizada (GWh)''] || 0))",
      "as": "pct"
    }
  ],
  "encoding": {
    "x": {
      "field": "Mês",
      "type": "temporal",
      "timeUnit": "yearmonth",
      "title": null,
      "axis": {
        "format": "%Y",
        "tickCount": "year",
        "labelAlign": "left",
        "labelPadding": 6
      }
    }
  },
  "layer": [
    {
      "mark": {
        "type": "bar",
        "color": "#252423",
        "width": {
          "band": 0.75
        }
      },
      "encoding": {
        "y": {
          "field": "Não realizada (GWh)",
          "type": "quantitative",
          "title": "GWh cortados (barras)",
          "axis": {
            "format": ",.0f",
            "tickCount": 4
          }
        },
        "tooltip": [
          {
            "field": "Mês",
            "type": "temporal",
            "timeUnit": "yearmonth",
            "title": "Mês",
            "format": "%m/%Y"
          },
          {
            "field": "Não realizada (GWh)",
            "title": "Não realizada (GWh)",
            "format": ",.1f"
          },
          {
            "field": "pct",
            "title": "% cortado",
            "format": ".1%"
          }
        ],
        "opacity": {
          "condition": {
            "test": "datum.__selected__ == ''off''",
            "value": 0.25
          },
          "value": 1
        }
      }
    },
    {
      "mark": {
        "type": "line",
        "color": "#E0B000",
        "strokeWidth": 2,
        "interpolate": "monotone"
      },
      "encoding": {
        "y": {
          "field": "pct",
          "type": "quantitative",
          "title": "% cortado (linha)",
          "axis": {
            "format": ".0%",
            "orient": "right",
            "grid": false,
            "tickCount": 4,
            "titleColor": "#967100"
          }
        }
      }
    }
  ],
  "resolve": {
    "scale": {
      "y": "independent"
    }
  }
}'
